  r=subprocess.run(['timeout','2','./build/fuzz_disasm',p],env=dict(os.environ,MSAN_OPTIONS='exit_code=86:halt_on_error=1'),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=3)
 except subprocess.TimeoutExpired:
  print('PYTIMEOUT',idx,p); break
 if r.returncode not in (0,):
  print('BAD',idx,p,r.returncode,'size',os.path.getsize(p))
  print((r.stdout+r.stderr).decode('latin1','replace')[:4000])
  break
 if idx and idx%1000==0: print('ok',idx, flush=True)
else:
 print('all ok')
